@startuml

class Factory {}

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + firstName : string
  + lastName : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + productTypeId : int
  + weight : double
}

class Material {
  + materialId : int
  + name : string
}

class Client {
  + clientId : int
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : int
  + orderDate : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
  + quantity : int
}

Factory "1" -- "*" Machine
Factory "1" -- "*" Worker
Machine "*" -- "*" Worker
Machine "1" -- "*" ProductType
ProductType "*" -- "1" Material
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "*" OrderLine
OrderLine "*" -- "1" ProductType

@enduml

